#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps it reachable; raw pointer was garbage-collected mid-match (crash in AddPoints).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UObject pointer without UPROPERTY, so the garbage collector destroyed the UArenaScoreTracker after ~1 minute; OnGoalScored then called AddPoints on a dangling pointer (EXCEPTION_ACCESS_VIOLATION at ArenaScoreTracker.cpp:18). Fixed with UPROPERTY() TObjectPtr.",
  "no_colors_cause": "DA_Primary palette is only loaded by string path via LoadObject, so the cooker never references it and it is not packaged (log: Couldn't find file for package /Game/Data/Palettes/DA_Primary); palette null -> fallback gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
